export const GOALS={mass:['Ganhar massa muscular','Desenvolver os músculos.'],strength:['Ganhar força','Melhorar a capacidade de levantar cargas.'],fitness:['Melhorar o condicionamento','Desenvolver resistência para o esforço.'],routine:['Criar uma rotina de treino','Começar ou voltar a treinar com consistência.']};
export const LEVELS={new:['Iniciante','Está começando, aprende os movimentos ou ainda não tem rotina consistente.'],regular:['Intermediário','Treina com regularidade e executa os movimentos habituais com autonomia.'],advanced:['Avançado','Tem experiência consistente com planejamento e progressão.']};
export const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
export function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
