export function profileDefaults(){return {goal:'',secondaryGoal:'',experience:'new',trainingMonths:'',returning:'',pauseMonths:'',familiarity:'',age:'',height:'',weight:'',comfort:'',days:3,scheduledDays:'auto',time:60,count:'auto',division:'movement',included:[],priorities:[],groups:[],equipment:[],preferred:[],excluded:[],restrictions:'',professionalReviewed:false,otherActivity:'',otherIntensity:'',otherDays:[],otherGroups:[],recovery:''}}
