export function minutes(exs){return Math.ceil(5+exs.reduce((s,e)=>{let ns=e.reps.match(/\d+/g)?.map(Number)||[10],avg=ns.reduce((a,b)=>a+b,0)/ns.length;return s+e.sets*(avg*3+e.rest)/60+1},0))}
