 if(b.plan){let p=b.plan;if(!safe(p.id)||!Array.isArray(p.templates)||!p.templates.length||p.templates.length>6||new Set(p.templates.map(t=>t.id)).size!==p.templates.length||!Array.isArray(p.calendar)||p.calendar.length<28||p.calendar.length>180)fail();for(let t of p.templates){if(!safe(t.id)||!text(t.name,300)||!Array.isArray(t.groups)||!t.groups.every(g=>GROUPS.includes(g))||!Array.isArray(t.exercises)||!t.exercises.length||t.exercises.length>10)fail();t.exercises.forEach(ex)}let dates=new Set();for(let d of p.calendar){if(!dateOk(d.date)||dates.has(d.date)||d.templateId!==null&&!p.templates.some(t=>t.id===d.templateId)||!['pending','rest','skipped','rescheduled','completed','partial'].includes(d.status)||d.rescheduledTo&&!dateOk(d.rescheduledTo))fail();dates.add(d.date)}if(p.profileSnapshot)checkP(p.profileSnapshot)}
